}", "middlewares/step_left_undone.py": """"A check before finishing: if the final message says "Not done:", send the agent back with what it left."""


def check(ctx, event):
    final = str(event.get('final_message', ''))
    if 'Not done:' in final:
        left = final.split('Not done:', 1)[1].strip()
        return {'action': 'block', 'message': 'Your message says this is not done: ' + left + ' Do it, then finish.'}
    return {'action': 'continue'}
